package com.shopsphere.dao;
import com.shopsphere.config.DBConnection; import java.sql.*; import java.util.*;
public class OrderHistoryDAO{public List<Map<String,Object>> findByUser(int id)throws SQLException{List<Map<String,Object>> out=new ArrayList<>();String q="SELECT order_id,total_amount,payment_method,payment_status,order_status,created_at FROM orders WHERE user_id=? ORDER BY created_at DESC";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,id);try(ResultSet r=s.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("orderId",r.getInt(1));m.put("total",r.getBigDecimal(2));m.put("paymentMethod",r.getString(3));m.put("paymentStatus",r.getString(4));m.put("orderStatus",r.getString(5));m.put("createdAt",r.getTimestamp(6));out.add(m);}}}return out;}}